    }
    if (Array.isArray(value)) {
        return value.map(normalizePrimitiveValue).filter(Boolean).join(", ");
    }
    if (typeof value === "object") {
        if (Object.prototype.hasOwnProperty.call(value, "value")) {
            return normalizePrimitiveValue(value.value);
        }
        if (Object.prototype.hasOwnProperty.call(value, "name")) {
            return normalizePrimitiveValue(value.name);
        }
        return "";
    }
    return String(value).trim();
}

function normalizeListValue(value) {
    if (value === undefined || value === null || value === "") {
        return [];
    }
    if (Array.isArray(value)) {
        return value.map(normalizePrimitiveValue).filter(Boolean);
    }
    if (typeof value === "object") {
        if (Object.prototype.hasOwnProperty.call(value, "value")) {
            return normalizeListValue(value.value);
        }
        return [];
    }
    return String(value)
        .split(/\r?\n|;|\|/)
        .map(function(item) { return item.trim(); })
        .filter(Boolean);
}

