    }
    if (normalized.indexOf("repeat") === 0 && normalized.indexOf("section") !== -1) {
        return "repeat_section_recut";
    }
    if (normalized.indexOf("recut") !== -1 || normalized.indexOf("deeper section") !== -1) {
        return "repeat_section_recut";
    }
    if (normalized.indexOf("repeat") === 0) {
        return "repeat_stain";
    }
    if (normalized.indexOf("special stain") === 0) {
        return "special_stain";
    }
    if (normalized.indexOf("impression cytology") !== -1) {
        return "special_stain";
    }
    return "routine_stain";
}

