      function refreshFilterOptions(){var current=filterEl.value||'all';filterEl.innerHTML='<option value="all">All sections</option>'+sections.map(function(section){return '<option value="'+section.key+'">'+section.title+'</option>';}).join('');filterEl.value=current;}
      async function load(){statusEl.textContent='Loading shared workflow cases...';clear(sectionsEl);try{var response=await fetch('/cases?limit=96',{cache:'no-store'});var items=await response.json();if(!response.ok){throw new Error('Could not load active cases.');}state.items=(Array.isArray(items)?items:[]).filter(function(item){return item && (item.caseId||item.patientId);});refreshFilterOptions();renderSections();}catch(error){addEmpty(sectionsEl,'Tech portal unavailable',error.message||'Could not load active cases.');statusEl.textContent=error.message||'Could not load active cases.';}}
