function deriveCaseIdFromBarcode(barcode) {
  var value = String(barcode || '').trim();
  if (!value) { return ''; }
  if (/^LAB-[A-Za-z0-9-]+$/i.test(value)) { return value.toUpperCase(); }
  if (value.indexOf('REPORT-') === 0) { return value.slice(7).toUpperCase(); }
  if (value.indexOf('LABREC-') === 0) { return value.slice(7).toUpperCase(); }
  if (value.indexOf('SLIDE-') === 0) {
    value = value.slice(6);
    if (/^LAB-[A-Za-z0-9-]+-S\d+$/i.test(value)) {
      return value.replace(/-S\d+$/i, '').toUpperCase();
    }
    return value.toUpperCase();
  }
  if (/^[A-Za-z0-9-]+$/i.test(value) && value.indexOf('LAB-') !== 0 && value.indexOf('PAT-') !== 0) {
    return ('LAB-' + value).toUpperCase();
  }
  return '';
}
