        }
      }
      form.addEventListener('submit', function(event){ event.preventDefault(); applyFilters(); });
      document.getElementById('audit-clear').addEventListener('click', function(){ form.reset(); applyFilters(); });
      document.getElementById('audit-export').addEventListener('click', function(){ downloadCsv(filtered); });
      document.getElementById('audit-print').addEventListener('click', function(){ window.print(); });
      load();
    })();
  </script>
</body>
</html>`;
}

